  "label_scope": "skin_sensitization_contact_allergy.v2",
  "skin_reaction_prediction": "risk",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C11", "C17", "C19", "C06", "C13", "C34", "C35"],
  "contradictory_card_ids": ["C09"],
  "prediction_basis_card_ids": ["C11", "C17", "C19", "C06", "C13", "C34", "C35"],
  "claims": [
    {
      "claim": "Human patch testing demonstrated allergic contact dermatitis to gentamicin and amikacin, and ribostamycin patch positivity; gentamicin is reported as a frequent sensitizer in atopic eczema patients. These aminoglycoside-class delayed-type positives transfer to the dihydrostreptomycin query.",
      "card_ids": ["C11", "C17", "C19", "C06", "C13"]
    },
    {
      "claim": "Aminoglycosides neomycin, streptomycin, and kanamycin are recognized human sensitizers despite false-negative LLNA results, so the single kanamycin guinea pig negative does not negate class-level risk.",
      "card_ids": ["C34", "C35", "C09"]
    },
    {
      "claim": "The L4 phototoxicity/irritation/local-damage records (amikacin local injury, glucoside irritation controls, protective trehalose/catalpol/2FL studies) are outside the sensitization endpoint and cannot support either prediction.",
      "card_ids": ["C48", "C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "phototoxicity_irritation_local_damage",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C48", "C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59"]
    }
  ],
  "evidence_gaps": [
    "No direct human patch test, LLNA, or guinea pig sensitization study on dihydrostreptomycin itself is available in the provided records.",
    "Transfer relies on structural and class analogy to other aminoglycosides, especially streptomycin, rather than query-specific experimental data.",
    "C08 is an immediate-type prick-test wheal rather than delayed-type contact allergy, so it is not counted as primary contact-allergy evidence.",
    "L4 records are phototoxicity, irritation, or local tissue damage and cannot inform the skin sensitization/contact allergy label.",
    "The physicochemical prior indicates very poor skin penetration and no obvious electrophilic alerts, but this is exposure context and structural prior, not endpoint proof.",
    "No aminoglycoside-specific sensitization AOP records were provided in the L3 bundle."
  ],
  "decision_summary": "Predicted risk. The query is a dihydrostreptomycin-class aminoglycoside. Transferable human patch-test positives for gentamicin, amikacin, and ribostamycin, plus recognition of aminoglycosides as human sensitizers despite LLNA false negatives, support skin sensitization/contact allergy risk. The single kanamycin guinea pig negative and poor skin-penetration prior do not overturn this. L4 phototoxicity/irritation/local-damage records are out of scope and do not change the decision."
}
